%prepend-module-path "/home/david/src/qore/git/module-xml/qlib"
%requires WSDL
foreach hash<auto> row in (
    {"name": "inherited type", "body": '<xs:element name="member" substitutionGroup="head"/><xs:element name="head" type="xs:int"/>'},
    {"name": "incompatible type", "body": '<xs:element name="member" substitutionGroup="head" type="xs:string"/><xs:element name="head" type="xs:int"/>'},
    {"name": "circular affiliation", "body": '<xs:element name="member" substitutionGroup="head" type="xs:int"/><xs:element name="head" substitutionGroup="member" type="xs:int"/>'},
    {"name": "final restriction", "body": '<xs:element name="member" substitutionGroup="head" type="xs:int"/><xs:element name="head" type="xs:decimal" final="restriction"/>'}
) {
    try {
        XsdSchema schema('<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema">' + row.body + '</xs:schema>');
        printf("%s: ACCEPTED; member type=%s\n", row.name, schema.getElement("", "member").type.name);
    } catch (hash<ExceptionInfo> ex) {
        printf("%s: REJECTED %s\n", row.name, ex.err);
    }
}

